step_business_items.query:
PREFIX id: <https://id.parliament.uk/>
PREFIX : <https://id.parliament.uk/schema/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?businessItem ?businessItemDate ?workPackage ?procedure ?procedureName ?workPackagedThing ?workpackagedThingName WHERE {

  ?step a :ProcedureStep;
  :name ?stepName;
  :procedureStepHasBusinessItem ?businessItem.
  OPTIONAL{ ?businessItem :businessItemDate ?businessItemDate.}
  OPTIONAL {?businessItem :businessItemHasBusinessItemWebLink ?businessItemLink }
  ?businessItem :businessItemHasWorkPackage ?workPackage.
  ?workPackage :workPackageHasProcedure ?procedure;
  :workPackageHasWorkPackagedThing ?workPackagedThing.
  ?procedure :name ?procedureName.
  ?workPackagedThing :name ?workpackagedThingName.
} ORDER BY DESC(?businessItemDate)  ?workpackagedThingName
LIMIT 5

treaty_work_packages.query:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX : <https://id.parliament.uk/schema/>
PREFIX id: <https://id.parliament.uk/>
SELECT DISTINCT ?paper ?papername ?workPackage ?businessItem ?combinedDate ?procedure ?procedure ?procedureName ?calculationStyle ?calculationStyleName (BOUND(?stepId3) AS ?hasCommitteeConcernsFlag)
(BOUND(?stepId4) AS ?hasMotionTabledFlag)  WHERE {

  ?paper a :Treaty.
  ?paper :name ?papername ;
  :workPackagedThingHasWorkPackage ?workPackage.
  OPTIONAL {   ?workPackage :workPackageHasBusinessItem ?businessItem .
    ?businessItem :businessItemHasProcedureStep ?step;
    :businessItemDate ?businessItemDate.
    FILTER (?step IN (id:isWn7s3K, id:cspzmb6w, id:ITNO9JWr, id:otscOTzB))}
  OPTIONAL {    ?workPackage :workPackageHasBusinessItem ?businessItem2 .
    ?businessItem2 :businessItemHasProcedureStep ?step2;
    :businessItemDate ?businessItemDate2.
    FILTER (?step2 IN (id:AmYrFxwO))}
  ?workPackage :workPackageHasProcedure ?procedure.
  ?procedure :name ?procedureName.
  OPTIONAL { ?workPackage :workPackageHasCalculationStyle ?calculationStyle.
    ?calculationStyle :name ?calculationStyleName. }
  OPTIONAL {
    ?workPackage :workPackageHasBusinessItem ?bi3 .
    ?bi3 :businessItemHasProcedureStep ?stepId3 .
    ?stepId3 :procedureStepHasProcedureStepCollectionMembership/
    :procedureStepCollectionMembershipHasProcedureStepCollection id:7CBVQcZF
  }

  OPTIONAL {
    ?workPackage :workPackageHasBusinessItem ?bi4 .
    ?bi4 :businessItemHasProcedureStep ?stepId4 .
    ?stepId4 :procedureStepHasProcedureStepCollectionMembership/
    :procedureStepCollectionMembershipHasProcedureStepCollection id:l3g2umNB
  }
  BIND(COALESCE(?businessItemDate, ?businessItemDate2) AS ?combinedDate)
} ORDER BY DESC(?combinedDate) ?papername
LIMIT 5

work_package.query:
PREFIX : <https://id.parliament.uk/schema/>
PREFIX id: <https://id.parliament.uk/>

SELECT * WHERE {
  ?paper a :WorkPackagedThing .
  ?paper :name ?paperName ;
  :workPackagedThingHasWorkPackage ?workPackage.

  OPTIONAL {?paper :workPackagedThingHasWorkPackagedThingWebLink ?workPackagedThingWebLink.}

  OPTIONAL {?paper :laidThingHasLaying ?laying.
    ?laying :layingDate ?laidDate;
    :businessItemHasProcedureStep ?step.

    FILTER (?step IN (id:isWn7s3K, id:cspzmb6w))}

  ?workPackage :workPackageHasProcedure ?procedure.
  ?procedure :name ?procedureName.

  OPTIONAL{ ?workPackage :workPackageHasCalculationStyle ?calculationStyle.
    ?calculationStyle :name ?calculationStyleName. }

}
LIMIT 5

step_procedures.query:
PREFIX id: <https://id.parliament.uk/>
PREFIX : <https://id.parliament.uk/schema/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?step ?stepName ?procedure ?procedureLabel ?procedureDescription WHERE {
  ?step a :ProcedureStep;
  :name ?stepName.

  {
    ?step :procedureStepIsFromProcedureRoute ?procedureRoute.
  } UNION {
    ?step :procedureStepIsToProcedureRoute ?procedureRoute.
  }

  ?procedureRoute :procedureRouteHasProcedure ?procedure.
  ?procedure :name ?procedureLabel.
  OPTIONAL { ?procedure :procedureDescription ?procedureDescription. }
}
ORDER BY ?procedureDisplayOrder ?procedureName
LIMIT 5
